    question: "ある製品の需要予測に「指数平滑法」を用いている。当期（第t期）の予測値が 200個、当期の実際の需要実績値が 240個 であった。平滑化定数 α ＝ 0.3 とするとき、来期（第t+1期）の需要予測値として、最も適切なものはどれか。",
