    question: "ある職場の機械の稼働率を「ワークサンプリング法」で調査したい。予備調査の結果、稼働率の推定値 p は 0.8（80%）であった。信頼度 95%（係数 2）のもとで、稼働率の「絶対誤差（e）」を ±0.04（±4%）以内に収めるために必要な観測回数（サンプル数 N）として、最も適切なものはどれか。",
