      "× 625回 は「相対誤差 S ＝ 0.04」とした場合（N ＝ 4(1－p) / (S^2・p) ＝ 4×0.2 / (0.0016×0.8) ＝ 625）の値です。問題文の「絶対誤差」と「相対誤差」の区別に注意してください。"
