      "× 逆です！赤・橙・黄などの暖色系（長波長）は手前に飛び出して見える「進出色」、青などの寒色系（短波長）は奥に引っ込んで見える「後退色」です。また、明るい色（高明度）は大きく見える「膨張色」、暗い色（低明度）は締まって見える「収縮色」です。",
