      "実験計画法において「直交表」を用いると、すべての因子のあらゆる水準の組み合わせ（総当たり実験）を 1回 の漏れもなく全通り実施しなければならなくなる。",
      "タグチメソッド（品質工学）における「パラメータ設計」では、温度変化や劣化などの誤差因子（ノイズ）に対して品質特性が最も敏感に大きくばらつく条件を最適条件として選定する。",
