      "○ 正しい！実験計画法の3原則は、①反復（誤差分散を見積もる）、②無作為化（系統的誤差を偶然誤差に転化する）、③局所管理（実験環境を均一なブロックに分けて誤差を分離する）です。",
      "× 直交表（L8直交表など）は、多数の因子がある場合に総当たり実験を行わず、「一部のバランスの取れた組み合わせだけを抜き出して少ない実験回数で効率よく主効果等を推定する」ためのツールです。",
      "× パラメータ設計（ロバスト設計）は、使用環境の変化や部品のばらつきといった「ノイズ（誤差因子）の影響を受けにくい（鈍感でばらつかない＝ロバスト性が高い）」制御因子の水準組み合わせを見つける手法です。",
      "× SN比（Signal-to-Noise Ratio：単位はデシベル dB）は、信号（理想の機能）に対する雑音（ばらつき）の比であり、「数値が大きいほど」ばらつきが小さく機能安定性が高い（ロバストである）ことを示します。"
