    question: "あるスーパーマーケットで全 1,000件 のレシート（買物カゴ）データを対象にバスケット分析を行ったところ、以下の結果が得られた。\n・商品Aを購入したレシート数：200件\n・商品Bを購入したレシート数：100件\n・商品Aと商品Bの両方を同時に購入したレシート数：50件\nこのとき、「商品Aを購入した顧客が商品Bも同時購入するルール（A ➔ B）」の「リフト値（Lift）」として、最も適切なものはどれか。",
